{'code': "from qgis.PyQt.QtWidgets import QMenu, QAction
from qgis.utils import plugins
mmqgis = plugins.get('mmqgis')
menu = mmqgis.mmqgis_menu
sub_info = []
animate_lines_action = None
for a in menu.actions():
    m = a.menu()
    if m is not None:
        sub_info.append({'submenu': a.text(), 'n': len(m.actions()), 'enabled': a.isEnabled(), 'visible': a.isVisible()})
        if 'animate' in (a.text() or '').lower():
            for sa in m.actions():
                if (sa.text() or '') == 'Animate Lines':
                    animate_lines_action = sa
    else:
        sub_info.append({'action': a.text(), 'enabled': a.isEnabled(), 'visible': a.isVisible()})
result = {
    'menu_title': menu.title(),
    'menu_enabled': menu.menuAction().isEnabled(),
    'menu_visible': menu.menuAction().isVisible(),
    'entries': sub_info,
    'animate_lines_enabled': animate_lines_action.isEnabled() if animate_lines_action else None,
}"}
